    unsigned long long v = (unsigned long long)(neg ? -s : s) * 100ULL;
    unsigned long long q = v / (unsigned long long)n, r = v % (unsigned long long)n;
    if (2ULL * r >= (unsigned long long)n) q += 1ULL;
    printf("%s%llu.%02llu\n", (neg && q > 0) ? "-" : "", q / 100ULL, q % 100ULL);
