int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    long long *res = (long long *)malloc(sizeof(long long) * (size_t)(n > 0 ? n : 1));
    if (!res) return 1;
    int k = 0;
    for (int i = 0; i < n; i++) {
        long long x;
        if (scanf("%lld", &x) != 1) break;
        int seen = 0;
        for (int j = 0; j < k; j++) {
            if (res[j] == x) {
                seen = 1;
                break;
            }
        }
        if (!seen) res[k++] = x;
    }
    for (int i = 0; i < k; i++) printf("%lld%c", res[i], i + 1 < k ? ' ' : '\n');
    free(res);
    return 0;
}

