#include <stdio.h>
#include <stdlib.h>

static int cmp_ll(const void *pa, const void *pb) {
    long long a = *(const long long *)pa;
    long long b = *(const long long *)pb;
    return (a > b) - (a < b);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    long long *a = (long long *)malloc(sizeof(long long) * (size_t)(n > 0 ? n : 1));
    if (!a) return 1;
    for (int i = 0; i < n; i++) {
        if (scanf("%lld", &a[i]) != 1) break;
    }
    qsort(a, (size_t)n, sizeof(long long), cmp_ll);
    long long ans = a[0];
    int best = 0;
    int i = 0;
    while (i < n) {
        int j = i;
        while (j < n && a[j] == a[i]) j++;
        int cnt = j - i;
        if (cnt > best) {
            best = cnt;
            ans = a[i];
        }
        i = j;
    }
    printf("%lld\n", ans);
    free(a);
    return 0;
}

