#include <stdio.h>
#include <stdlib.h>

static int cmp_ll(const void *pa, const void *pb) {
    long long x = *(const long long *)pa;
    long long y = *(const long long *)pb;
    return (x > y) - (x < y);
}

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;
    long long *a = (long long *)malloc(sizeof(long long) * (size_t)n);
    if (!a) return 0;
    for (int i = 0; i < n; ++i) scanf("%lld", &a[i]);
    qsort(a, (size_t)n, sizeof(long long), cmp_ll);
    printf("%lld\n", a[k - 1]);
    free(a);
    return 0;
}

