#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long key;
    long long cnt;
    int used;
} Slot;

static Slot *tab;
static size_t cap;

static size_t slot_index(long long key) {
    unsigned long long x = (unsigned long long)key;
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    size_t i = (size_t)(x & (unsigned long long)(cap - 1));
    while (tab[i].used && tab[i].key != key) i = (i + 1) & (cap - 1);
    return i;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    cap = 1;
    while (cap < (size_t)(n + 1) * 2) cap <<= 1;
    tab = calloc(cap, sizeof(Slot));
    if (!tab) return 1;
    size_t z = slot_index(0);
    tab[z].used = 1;
    tab[z].key = 0;
    tab[z].cnt = 1;
    long long prefix = 0, ans = 0;
    for (int i = 0; i < n; ++i) {
        long long a;
        if (scanf("%lld", &a) != 1) break;
        prefix += a;
        size_t idx = slot_index(prefix);
        if (tab[idx].used) {
            ans += tab[idx].cnt;
        } else {
            tab[idx].used = 1;
            tab[idx].key = prefix;
            tab[idx].cnt = 0;
        }
        tab[idx].cnt += 1;
    }
    printf("%lld\n", ans);
    free(tab);
    return 0;
}

