#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long key;
    long long cnt;
    int used;
} Slot;

typedef struct {
    long long val;
    long long cnt;
} Pair;

static Slot *tab;
static size_t cap;

static size_t slot_index(long long key) {
    unsigned long long x = (unsigned long long)key;
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    size_t i = (size_t)(x & (unsigned long long)(cap - 1));
    while (tab[i].used && tab[i].key != key) i = (i + 1) & (cap - 1);
    return i;
}

static int cmp_pair(const void *pa, const void *pb) {
    const Pair *a = (const Pair *)pa;
    const Pair *b = (const Pair *)pb;
    if (a->cnt != b->cnt) return a->cnt > b->cnt ? -1 : 1;
    if (a->val != b->val) return a->val < b->val ? -1 : 1;
    return 0;
}

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;
    cap = 1;
    while (cap < (size_t)n * 2 + 2) cap <<= 1;
    tab = calloc(cap, sizeof(Slot));
    if (!tab) return 1;
    for (int i = 0; i < n; ++i) {
        long long v;
        if (scanf("%lld", &v) != 1) break;
        size_t idx = slot_index(v);
        if (!tab[idx].used) {
            tab[idx].used = 1;
            tab[idx].key = v;
            tab[idx].cnt = 0;
        }
        tab[idx].cnt += 1;
    }
    Pair *pairs = malloc(sizeof(Pair) * (size_t)n);
    if (!pairs) return 1;
    int m = 0;
    for (size_t i = 0; i < cap; ++i) {
        if (tab[i].used) {
            pairs[m].val = tab[i].key;
            pairs[m].cnt = tab[i].cnt;
            ++m;
        }
    }
    qsort(pairs, (size_t)m, sizeof(Pair), cmp_pair);
    for (int i = 0; i < k && i < m; ++i) {
        if (i) putchar(' ');
        printf("%lld", pairs[i].val);
    }
    putchar('\n');
    free(pairs);
    free(tab);
    return 0;
}

