        Map<Long, Integer> freq = new HashMap<>();
        for (int i = 0; i < n; ++i) {
            long v = Long.parseLong(tok[1 + i]);
            freq.merge(v, 1, Integer::sum);
        }
        List<long[]> items = new ArrayList<>();
        for (Map.Entry<Long, Integer> e : freq.entrySet())
            items.add(new long[]{e.getKey(), e.getValue()});
        items.sort((p, q) -> p[1] != q[1] ? Long.compare(q[1], p[1]) : Long.compare(p[0], q[0]));
        StringBuilder out = new StringBuilder();
        boolean first = true;
        for (long[] p : items) {
            for (long c = 0; c < p[1]; ++c) {
                if (!first) out.append(' ');
                out.append(p[0]);
                first = false;
            }
        }
        out.append('\n');
        System.out.print(out);
    }
}

