    long long cap;
    if (!(std::cin >> n >> cap)) return 0;
    std::vector<Item> items(n);
    for (int i = 0; i < n; ++i) std::cin >> items[i].w >> items[i].v;
    std::sort(items.begin(), items.end(), [](const Item &a, const Item &b) {
        long long lhs = a.v * b.w;
        long long rhs = b.v * a.w;
        if (lhs != rhs) return lhs > rhs;
        return a.w < b.w;
    });
    long long total = 0;
    for (int i = 0; i < n && cap > 0; ++i) {
        if (items[i].w <= cap) {
            cap -= items[i].w;
            total += items[i].v * 100;
        } else {
            long long t = cap * items[i].v;
            long long q = t / items[i].w;
            long long r = t % items[i].w;
            total += q * 100 + (r * 200 + items[i].w) / (2 * items[i].w);
            cap = 0;
        }
    }
    std::cout << total / 100 << "." << (total % 100 < 10 ? "0" : "") << total % 100 << "\n";
    return 0;
}

