    std::vector<std::vector<int>> adj(n);
    std::vector<int> indeg(n, 0);
    for (int i = 0; i < m; ++i) {
        int u, v;
        std::cin >> u >> v;
        --u;
        --v;
        adj[u].push_back(v);
        ++indeg[v];
    }
    std::priority_queue<int, std::vector<int>, std::greater<int>> heap;
    for (int i = 0; i < n; ++i)
        if (indeg[i] == 0) heap.push(i);
    std::vector<int> order;
    order.reserve(n);
    while (!heap.empty()) {
        int u = heap.top();
        heap.pop();
        order.push_back(u);
        for (size_t k = 0; k < adj[u].size(); ++k) {
            int v = adj[u][k];
            --indeg[v];
            if (indeg[v] == 0) heap.push(v);
        }
    }
    if ((int)order.size() < n) {
        std::cout << "IMPOSSIBLE\n";
    } else {
        for (int i = 0; i < n; ++i) {
            if (i) std::cout << ' ';
            std::cout << order[i] + 1;
        }
        std::cout << "\n";
    }
    return 0;
}

