static int *heap;
static int hsize = 0;

static void heap_push(int x) {
    int i = hsize++;
    heap[i] = x;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (heap[p] <= heap[i]) break;
        int t = heap[p];
        heap[p] = heap[i];
        heap[i] = t;
        i = p;
    }
}

static int heap_pop(void) {
    int top = heap[0];
    --hsize;
    heap[0] = heap[hsize];
    int i = 0;
    for (;;) {
        int l = 2 * i + 1, r = l + 1, m = i;
        if (l < hsize && heap[l] < heap[m]) m = l;
        if (r < hsize && heap[r] < heap[m]) m = r;
        if (m == i) break;
        int t = heap[m];
        heap[m] = heap[i];
        heap[i] = t;
        i = m;
    }
    return top;
}

