int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int r, c;
    if (!(std::cin >> r >> c)) return 0;
    std::vector<int> grid(r * c);
    for (int i = 0; i < r * c; ++i) std::cin >> grid[i];
    std::vector<int> dist(r * c, -1);
    std::queue<int> q;
    int fresh = 0;
    for (int i = 0; i < r * c; ++i) {
        if (grid[i] == 2) {
            dist[i] = 0;
            q.push(i);
        } else if (grid[i] == 1) {
            ++fresh;
        }
    }
    int minutes = 0;
    const int dx[4] = {1, -1, 0, 0};
    const int dy[4] = {0, 0, 1, -1};
    while (!q.empty()) {
        int cur = q.front();
        q.pop();
        int x = cur / c, y = cur % c;
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx >= 0 && nx < r && ny >= 0 && ny < c) {
                int ni = nx * c + ny;
                if (grid[ni] == 1 && dist[ni] == -1) {
                    dist[ni] = dist[cur] + 1;
                    if (dist[ni] > minutes) minutes = dist[ni];
                    --fresh;
                    q.push(ni);
                }
            }
        }
    }
    std::cout << (fresh == 0 ? minutes : -1) << "\n";
    return 0;
}

