            int j = i + length - 1;
            long long best = -1;
            for (int k = i; k < j; ++k) {
                long long v = dp[i][k] + dp[k + 1][j] + d[i - 1] * d[k] * d[j];
                if (best < 0 || v < best) best = v;
            }
            dp[i][j] = best;
        }
    }
    std::cout << dp[1][n] << "\n";
    return 0;
}

