#include <iostream>

static int full = 0;
static long long total = 0;

static void dfs(int cols, int diag1, int diag2) {
    if (cols == full) {
        ++total;
        return;
    }
    int avail = full & ~(cols | diag1 | diag2);
    while (avail) {
        int bit = avail & (-avail);
        avail ^= bit;
        dfs(cols | bit, ((diag1 | bit) << 1) & full, (diag2 | bit) >> 1);
    }
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int n;
    if (!(std::cin >> n)) return 0;
    full = (1 << n) - 1;
    total = 0;
    dfs(0, 0, 0);
    std::cout << total << "\n";
    return 0;
}

