            tree[p] += x;
            p >>= 1;
            while (p >= 1) {
                tree[p] = tree[2 * p] + tree[2 * p + 1];
                p >>= 1;
            }
        } else {
            int l, r;
            std::cin >> l >> r;
            int a = size + l - 1;
            int b = size + r;
            long long s = 0;
            while (a < b) {
                if (a & 1) {
                    s += tree[a];
                    ++a;
                }
                if (b & 1) {
                    --b;
                    s += tree[b];
                }
                a >>= 1;
                b >>= 1;
