#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXNODE 1000002

static int *head, *cnt, *eto, *enext;
static char *ech;
static int nodes, ne;

int find_child(int node, char c) {
    int e = head[node];
    while (e != -1) {
        if (ech[e] == c) return eto[e];
        e = enext[e];
    }
    return -1;
}

void add_child(int node, char c, int nn) {
    eto[ne] = nn;
    ech[ne] = c;
    enext[ne] = head[node];
    head[node] = ne;
    ++ne;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    head = (int *)malloc(sizeof(int) * (size_t)MAXNODE);
    cnt = (int *)calloc((size_t)MAXNODE, sizeof(int));
    eto = (int *)malloc(sizeof(int) * (size_t)MAXNODE);
    enext = (int *)malloc(sizeof(int) * (size_t)MAXNODE);
    ech = (char *)malloc((size_t)MAXNODE);
    if (!head || !cnt || !eto || !enext || !ech) return 0;
    head[0] = -1;
    nodes = 1;
    ne = 0;
    char *buf = (char *)malloc((size_t)MAXNODE);
    if (!buf) return 0;
    for (int i = 0; i < n; ++i) {
        if (scanf("%s", buf) != 1) break;
        int node = 0;
        for (char *p = buf; *p; ++p) {
            char c = *p;
            int nxt = find_child(node, c);
            if (nxt == -1) {
                int nn = nodes++;
                head[nn] = -1;
                cnt[nn] = 0;
                add_child(node, c, nn);
                nxt = nn;
            }
            node = nxt;
            cnt[node] += 1;
        }
    }
    int q;
    if (scanf("%d", &q) != 1) q = 0;
    for (int t = 0; t < q; ++t) {
        if (scanf("%s", buf) != 1) break;
        int node = 0;
        int ok = 1;
        for (char *p = buf; *p; ++p) {
            int nxt = find_child(node, *p);
            if (nxt == -1) { ok = 0; break; }
            node = nxt;
        }
        printf("%d\n", ok ? cnt[node] : 0);
    }
    free(buf);
    free(head);
    free(cnt);
    free(eto);
    free(enext);
    free(ech);
    return 0;
}

