#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int to;
    long long w;
    int next;
} Edge;

static long long *hdist;
static int *hnode;
static int hsize;

static void heap_push(long long d, int node) {
    int i = hsize++;
    hdist[i] = d;
    hnode[i] = node;
    while (i > 0) {
        int par = (i - 1) / 2;
        if (hdist[par] <= hdist[i]) break;
        long long td = hdist[par]; hdist[par] = hdist[i]; hdist[i] = td;
        int tn = hnode[par]; hnode[par] = hnode[i]; hnode[i] = tn;
        i = par;
    }
}

static void heap_pop(long long *d, int *node) {
    *d = hdist[0];
    *node = hnode[0];
    --hsize;
    if (hsize > 0) {
        hdist[0] = hdist[hsize];
        hnode[0] = hnode[hsize];
        int i = 0;
        for (;;) {
            int l = 2 * i + 1, r = 2 * i + 2, s = i;
            if (l < hsize && hdist[l] < hdist[s]) s = l;
            if (r < hsize && hdist[r] < hdist[s]) s = r;
            if (s == i) break;
            long long td = hdist[s]; hdist[s] = hdist[i]; hdist[i] = td;
            int tn = hnode[s]; hnode[s] = hnode[i]; hnode[i] = tn;
            i = s;
        }
    }
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;
    Edge *edges = (Edge *)malloc(sizeof(Edge) * (size_t)(m + 1));
    int *head = (int *)malloc(sizeof(int) * (size_t)(n + 1));
    long long *dist = (long long *)malloc(sizeof(long long) * (size_t)(n + 1));
    hdist = (long long *)malloc(sizeof(long long) * (size_t)(m + n + 5));
    hnode = (int *)malloc(sizeof(int) * (size_t)(m + n + 5));
    if (!edges || !head || !dist || !hdist || !hnode) return 0;
    for (int i = 1; i <= n; ++i) head[i] = -1;
    for (int i = 0; i < m; ++i) {
        int u, v;
        long long w;
        scanf("%d %d %lld", &u, &v, &w);
        edges[i].to = v;
        edges[i].w = w;
        edges[i].next = head[u];
        head[u] = i;
    }
    const long long INF = (long long)4e18;
    for (int i = 1; i <= n; ++i) dist[i] = INF;
    dist[1] = 0;
    hsize = 0;
    heap_push(0, 1);
    while (hsize > 0) {
        long long d;
        int u;
        heap_pop(&d, &u);
        if (d > dist[u]) continue;
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            long long nd = d + edges[e].w;
            if (nd < dist[v]) {
                dist[v] = nd;
                heap_push(nd, v);
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        if (i > 1) printf(" ");
        if (dist[i] >= INF) printf("-1");
        else printf("%lld", dist[i]);
    }
    printf("\n");
    free(edges);
    free(head);
    free(dist);
    free(hdist);
    free(hnode);
    return 0;
}

