public class Main {
    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() throws IOException { return Integer.parseInt(next()); }
        long nextLong() throws IOException { return Long.parseLong(next()); }
    }

    static class Edge {
        int to;
        long w;
        Edge(int to, long w) { this.to = to; this.w = w; }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;
        int n = Integer.parseInt(first);
        int m = fs.nextInt();
        ArrayList<Edge>[] adj = new ArrayList[n + 1];
        for (int i = 1; i <= n; ++i) adj[i] = new ArrayList<Edge>();
        for (int i = 0; i < m; ++i) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            long w = fs.nextLong();
            adj[u].add(new Edge(v, w));
        }
        final long INF = (long) 4e18;
        long[] dist = new long[n + 1];
        Arrays.fill(dist, INF);
        dist[1] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<long[]>(new Comparator<long[]>() {
            public int compare(long[] a, long[] b) {
                return Long.compare(a[0], b[0]);
            }
        });
        pq.add(new long[] {0L, 1L});
        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            long d = top[0];
            int u = (int) top[1];
            if (d > dist[u]) continue;
            for (Edge e : adj[u]) {
                long nd = d + e.w;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.add(new long[] {nd, e.to});
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; ++i) {
            if (i > 1) sb.append(' ');
            sb.append(dist[i] >= INF ? -1 : dist[i]);
        }
        sb.append('\n');
        System.out.print(sb);
    }
}

