#include <iostream>
#include <vector>

static long long mulmod(long long a, long long b, long long m) {
    long long res = 0;
    a %= m;
    while (b > 0) {
        if (b & 1LL) {
            res += a;
            if (res >= m) res -= m;
        }
        a += a;
        if (a >= m) a -= m;
        b >>= 1;
    }
    return res;
}

static long long modinv(long long a, long long m) {
    long long old_r = a % m, r = m;
    long long old_s = 1, s = 0;
    while (r != 0) {
        long long q = old_r / r;
        long long tr = old_r - q * r;
        old_r = r;
        r = tr;
        long long ts = old_s - q * s;
        old_s = s;
        s = ts;
    }
    old_s %= m;
    if (old_s < 0) old_s += m;
    return old_s;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int n;
    if (!(std::cin >> n)) return 0;
    std::vector<long long> av, mv;
    for (int i = 0; i < n; ++i) {
        long long a, m;
        std::cin >> a >> m;
        if (m > 1) {
            av.push_back(a % m);
            mv.push_back(m);
        }
    }
    if (av.empty()) {
        std::cout << 0 << "\n";
        return 0;
    }
    long long x = av[0], mod = mv[0];
    for (size_t i = 1; i < av.size(); ++i) {
        long long a = av[i], m = mv[i];
        long long diff = (a - x) % m;
        if (diff < 0) diff += m;
        long long inv = modinv(mod % m, m);
        long long t = mulmod(diff, inv, m);
        x = x + mod * t;
        mod = mod * m;
        x %= mod;
    }
    std::cout << (x % mod) << "\n";
    return 0;
}

