        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;
        int n = Integer.parseInt(first);
        long[] av = new long[n];
        long[] mv = new long[n];
        int cnt = 0;
        for (int i = 0; i < n; ++i) {
            long a = Long.parseLong(fs.next());
            long m = Long.parseLong(fs.next());
            if (m > 1) {
                av[cnt] = a % m;
                mv[cnt] = m;
                ++cnt;
            }
        }
        if (cnt == 0) {
            System.out.println(0);
            return;
        }
        long x = av[0], mod = mv[0];
        for (int i = 1; i < cnt; ++i) {
            long a = av[i], m = mv[i];
            BigInteger bm = BigInteger.valueOf(m);
            long diff = ((a % m - x % m) % m + m) % m;
            BigInteger inv = BigInteger.valueOf(mod % m).modInverse(bm);
            long t = BigInteger.valueOf(diff).multiply(inv).mod(bm).longValue();
            x = x + mod * t;
            mod = mod * m;
            x %= mod;
        }
        System.out.println(x % mod);
    }
}

