import sys


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])
    a, b = 0, 1 % m
    if n > 0:
        bits = n.bit_length()
        for i in range(bits - 1, -1, -1):
            two_b = (2 * b) % m
            c = a * ((two_b - a) % m) % m
            d = (a * a + b * b) % m
            if (n >> i) & 1:
                a, b = d, (c + d) % m
            else:
                a, b = c, d
    sys.stdout.write(str(a % m) + "\n")


main()

