#include <iostream>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    long long n, m;
    if (!(std::cin >> n >> m)) return 0;
    unsigned long long nn = (unsigned long long)n;
    long long a = 0, b = 1 % m;
    if (nn > 0) {
        int bits = 0;
        unsigned long long t = nn;
        while (t) {
            ++bits;
            t >>= 1;
        }
        for (int i = bits - 1; i >= 0; --i) {
            long long two_b = (2 * b) % m;
            long long f1 = (two_b - a) % m;
            if (f1 < 0) f1 += m;
            long long c = a * f1 % m;
            long long d = (a * a + b * b) % m;
            if ((nn >> i) & 1ULL) {
                a = d;
                b = (c + d) % m;
            } else {
                a = c;
                b = d;
            }
        }
    }
    std::cout << (a % m) << "\n";
    return 0;
}

