        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;
        long n = Long.parseLong(first);
        long mod = Long.parseLong(fs.next());
        long a = 0, b = 1 % mod;
        int bits = 64 - Long.numberOfLeadingZeros(n);
        for (int i = bits - 1; i >= 0; --i) {
            long twoB = (2 * b) % mod;
            long f1 = ((twoB - a) % mod + mod) % mod;
            long c = a * f1 % mod;
            long d = (a * a + b * b) % mod;
            if (((n >> i) & 1L) == 1L) {
                a = d;
                b = (c + d) % mod;
            } else {
                a = c;
                b = d;
            }
        }
        System.out.println(a % mod);
    }
}
